CREATE TABLE attendance_correction_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),section_id uuid NOT NULL REFERENCES sections(id),school_date date NOT NULL,requested_by uuid NOT NULL REFERENCES app_users(id),reason text NOT NULL,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','APPROVED','REJECTED')),reviewed_by uuid REFERENCES app_users(id),review_reason text,created_at timestamptz NOT NULL DEFAULT now());
